import importlib
import sys
import tempfile
from importlib.resources import files
from pathlib import Path

from grpc_tools import protoc

# Version 1 of the contract, as old clients and services still have it.
OLD = """
syntax = "proto3";
package snapshot.old;
enum RunStatus {
  RUN_STATUS_UNSPECIFIED = 0;
  RUN_STATUS_RUNNING = 1;
  RUN_STATUS_SUCCEEDED = 2;
}
message RunEvent {
  int64 seq = 1;
  string run_id = 2;
  RunStatus status = 3;
  string payload_json = 4;
}
"""

_WELL_KNOWN = str(files("grpc_tools") / "_proto")
_OUT = tempfile.TemporaryDirectory(dir=".")


def compile_proto(name: str, text: str) -> int:
    """Compile text as <name>.proto into Python (<name>_pb2); returns protoc's exit code (0 = success)."""
    (Path(_OUT.name) / f"{name}.proto").write_text(text)
    return protoc.main(["protoc", f"-I{_OUT.name}", f"-I{_WELL_KNOWN}", f"--python_out={_OUT.name}", f"{_OUT.name}/{name}.proto"])


def load(name: str):
    """Import the module compile_proto generated for <name>.proto."""
    if _OUT.name not in sys.path:
        sys.path.insert(0, _OUT.name)
    return importlib.import_module(f"{name}_pb2")

