type Options = {
  deadlineMs: number; // overall budget for every attempt and every backoff together
  maxAttempts: number;
  retryable: ReadonlySet<number>; // error codes worth retrying
  baseMs?: number; // default 100
  capMs?: number; // default 2000
  now?: () => number;
  sleep?: (ms: number) => Promise<void>;
  random?: () => number;
};

/**
 * Call fn(remaining ms of the overall deadline), retrying retryable errors with full-jitter backoff:
 * delay = floor(random() * min(capMs, baseMs * 2 ** attempt)), attempt counting from 0.
 * Rethrow the last error when it is not retryable, attempts run out, or the backoff would reach the deadline.
 * If no time is left before an attempt, throw rpcError(DEADLINE_EXCEEDED, ...).
 */
export async function callWithRetry<T>(fn: (attemptTimeoutMs: number) => Promise<T>, opts: Options): Promise<T> {
  throw new Error('Not implemented');
}

