type RpcError = Error & { code: number };
const UNAVAILABLE = 14;
const INVALID_ARGUMENT = 3;
const DEADLINE_EXCEEDED = 4;
const rpcError = (code: number, message: string): RpcError => Object.assign(new Error(message), { code });

